import{_ as n,c as e,e as l,a as i,d as t,w as p,r as h,o as k,b as r}from"./app-CHV3pEDi.js";const d="/assets/%E5%B1%80%E9%83%A8%E5%8F%98%E9%87%8F%E6%A0%88%E5%86%85%E5%AD%98%E5%B8%83%E5%B1%80-yJssmLRP.jpg",c="/assets/%E5%A4%A7%E6%95%B0%E7%BB%84%E6%A0%88%E6%BA%A2%E5%87%BA%E5%86%85%E5%AD%98%E5%9B%BE-CIIl1j6D.jpg",g={};function o(v,s){const a=h("VPLink");return k(),e("div",null,[s[4]||(s[4]=l(`<p>刚刚帮一位学习RTOS课程的同学调试他的工程时，发现他的程序运行一段时间后就死机了，但是复位后又能正常跑，但是过一会儿又死。</p><p>通过加入测试代码并反复测试分析，最终发现问题出现在了一个大数组上。简单来说，他写了这样一段代码：</p><div class="language-c line-numbers-mode" data-highlighter="shiki" data-ext="c" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-c"><span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">void</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> parse_protocol</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">(</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">void</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">)</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">{</span></span>
<span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">    uint16_t</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;"> frame</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">[</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;">1024</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">];</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">    /* ... 后面是解析逻辑 ... */</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>就语法而言，这段代码本身没有任何问题。但是，聪明的你可能意识到：函数中定义了一个大型的数组，会不会是它造成的？</p><p>实际确实是这样，有的同学可能想不通：<strong>我之前在PC机上写程序也这么干，从来没出过问题，为什么在这里就不行？</strong></p><p>在接下来的文章，我将深入分析：为什么在嵌入式环境中不能这么做？</p><h2 id="局部变量存放到哪里" tabindex="-1"><a class="header-anchor" href="#局部变量存放到哪里"><span>局部变量存放到哪里</span></a></h2><p>要理解这件事，我们得先搞清楚C语言里的局部变量，到底存在哪里。</p><p>答案很简单：<strong>函数内部定义的局部变量，默认放在栈上。</strong></p><p>编译器在编译代码时，当碰到函数时，会根据这个函数里所有局部变量的总大小，在栈上预留出一段空间，这一段空间就叫这个<strong>函数的栈帧</strong>。<strong>每调用一层函数，栈帧便会增加一层，用于放置不同函数的局部变量等信息</strong>。</p><p>例如，假设有A和B两个函数，其代码如下：</p><div class="language-c line-numbers-mode" data-highlighter="shiki" data-ext="c" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-c"><span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">void</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> func_B</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">(</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">void</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">)</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">{</span></span>
<span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">    int</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> x</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">;</span></span>
<span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">    char</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;"> big</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">[</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;">1024</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">];</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">  /* 大局部数组 */</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">    /* ... */</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">void</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> func_A</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">(</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">void</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">)</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">{</span></span>
<span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">    int</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> a</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">;</span></span>
<span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">    char</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;"> buf</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">[</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;">16</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">];</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">    func_B</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">();</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">  /* A调用B */</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>当A调用B时，整个栈帧如下所示。</p><p><img src="`+d+'" alt="局部变量栈内存布局"></p><p>从图中可以看到，栈从高地址向低地址生长。</p><p>最上面是函数A的栈帧，里面保存了A的返回地址、需要保存的寄存器，以及A的局部变量a和buf[16]。当A调用B时，又会在栈上压入B的栈帧，包括B的返回地址、寄存器，以及B的局部变量x和big[1024]。SP指针始终指向当前栈顶，也就是B的栈帧位置。</p><h2 id="大数组带来的问题" tabindex="-1"><a class="header-anchor" href="#大数组带来的问题"><span>大数组带来的问题</span></a></h2><p>在嵌入式环境中，内存资源是非常有限的。通常情况下，我们仅会为程序分配有限的栈空间。</p><p>在这位同学的项目中，他创建了一个任务，分配了2048字节的任务栈。通常情况下，该任务只调用某些栈需求量较小的函数，加起来只用了300多字节，看起来栈空间非常宽裕。但是，当调用parse_protocol()时，就需要为frame分配2048字节的栈空间。</p><p><img src="'+c+`" alt="大数组栈溢出内存图"></p><p>从图中可以看到，业务函数的栈帧占了300字节，再加上内部调用parse_protocol()时，frame[1024]占了2048字节，总共需要2348字节。显然，这已经超过了任务栈2048字节的上限。此时，栈指针就会越过栈底，把栈外面的内存区域给覆盖掉。</p><p><strong>这些被覆盖的区域可能存放着其他重要的数据，比如：其他任务的栈或代码 、全局变量、OS内核的关键数据结构。</strong></p><p>这就是为什么会出现&quot;运行一段时间后突然死机，复位后又正常&quot;的现像，因为：溢出的时机不确定，被覆盖的内存区域什么时候被读取也不确定。</p><h2 id="解决方法" tabindex="-1"><a class="header-anchor" href="#解决方法"><span>解决方法</span></a></h2><p>既然已经知道问题的根源，那么解决起来就很容易了，常见的方法有以下几种：</p><h3 id="加static关键字" tabindex="-1"><a class="header-anchor" href="#加static关键字"><span>加static关键字</span></a></h3><p>当给局部变量加上static关键字时，这个变量不再放在栈上，而是放到了全局数据区。<strong>如果是未初始化的，放在.bss段；如果有初始值，放在.data段</strong>。</p><div class="language-c line-numbers-mode" data-highlighter="shiki" data-ext="c" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-c"><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">/* 加static后，数组不占栈空间 */</span></span>
<span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">void</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> parse_protocol</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">(</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">void</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">)</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">{</span></span>
<span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">    static</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> uint16_t</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;"> frame</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">[</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;">1024</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">];</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">    /* ... 解析逻辑 ... */</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这种方法的缺点也很明显：<strong>变量的生命周期从函数调用期间变成了整个程序运行期间</strong>。也就是说，即便函数未被调用，该变量始终占用一大块内存空间。</p><p>此外，如果该函数会被多个任务同时调用，或者在中断里也会被调用，那<strong>该局部变量就需要加锁保护，否则会出现数据访问冲突的问题</strong>。</p><h3 id="定义为全局变量" tabindex="-1"><a class="header-anchor" href="#定义为全局变量"><span>定义为全局变量</span></a></h3><p>如果不加static关键字，直接定义成全局变量，作用效果类似，缺点也是类似的。</p><p><strong>二者的主要区别在于：全局变量的作用域是整个文件，甚至整个程序。</strong></p><h3 id="使用动态内存分配" tabindex="-1"><a class="header-anchor" href="#使用动态内存分配"><span>使用动态内存分配</span></a></h3><p><strong>如果只是希望临时使用一大块内存空间，可以考虑从堆中动态分配内存</strong>。当需要的时候用malloc从堆上申请内存，用完之后用free释放掉。</p><div class="language-c line-numbers-mode" data-highlighter="shiki" data-ext="c" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-c"><span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">void</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> parse_protocol</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">(</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">void</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">)</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">{</span></span>
<span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">    uint16_t</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> *</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">frame </span><span style="--shiki-light:#999999;--shiki-dark:#666666;">=</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> malloc</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">(</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;">1024</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> *</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> sizeof</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">(</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">uint16_t</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">));</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">    /* ... 解析逻辑 ... */</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">    free</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">(</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">frame</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">);</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>当采用这种方案时，栈中只需要保存frame这个指针（4字节），实际的内存块从堆中分配，不会占用栈空间。</p><p>不过，采用这种方式缺点也很明显：</p><ol><li>动态内存分配会产生内存碎片，频繁申请释放可能导致堆空间不足。</li><li>malloc()的执行时间不确定：可能影响实时性。</li><li>容易忘记调用free()，引发内存泄漏。</li></ol><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span>总结</span></a></h2><p>综上所述，<strong>最好是不要在栈上放大的局部变量，以免发生栈溢出的问题</strong>。</p><p>当需要使用大的变量时，可以考虑改为静态变量或全局变量，或者也可以改用动态内存分配从堆上申请。具体用哪种，需要综合函数会不会被并发调用、对实时性的要求、以及内存碎片的承受能力这几方面进行权衡。</p><h2 id="写在最后" tabindex="-1"><a class="header-anchor" href="#写在最后"><span>写在最后</span></a></h2><p>如果只停留在&quot;局部数组别开太大&quot;这条经验上，遇到多层函数嵌套还是会踩坑。如果想真正理解，就得回到栈帧布局和任务栈初始化这些细节，看清楚每次调用到底从栈上切走了多少，现场才能一眼算出这行代码吃掉了多少栈。我在《从0手写嵌入式操作系统》的第3章里，就是带着大家把栈的初始化和栈帧的布局一行一行写出来的。</p><hr>`,45)),i("blockquote",null,[s[1]||(s[1]=i("p",null,"如果你希望系统地学习RTOS底层原理，可以了解我的《RTOS开发与实战》课程。",-1)),s[2]||(s[2]=i("p",null,"课程不是简单地讲解FreeRTOS API的使用，而是带你从零开始编写一个RTOS内核，逐步实现任务管理、任务调度、上下文切换、同步与通信等核心机制，并通过一个远程温湿度监控设备项目，将操作系统原理应用到实际嵌入式开发中。",-1)),s[3]||(s[3]=i("p",null,"适合希望深入理解RTOS工作原理、提升嵌入式底层开发能力的同学。",-1)),i("p",null,[t(a,{href:"/blog/diyrtos/"},{default:p(()=>[...s[0]||(s[0]=[r("课程详情",-1)])]),_:1})])])])}const A=n(g,[["render",o]]),u=JSON.parse('{"path":"/tech/rtos100/g7ysdksn/","title":"为什么局部大数组容易导致栈溢出","lang":"zh-CN","frontmatter":{"title":"为什么局部大数组容易导致栈溢出","createTime":"2026/11/10 14:55:14","permalink":"/tech/rtos100/g7ysdksn/","description":"刚刚帮一位学习RTOS课程的同学调试他的工程时，发现他的程序运行一段时间后就死机了，但是复位后又能正常跑，但是过一会儿又死。 通过加入测试代码并反复测试分析，最终发现问题出现在了一个大数组上。简单来说，他写了这样一段代码： 就语法而言，这段代码本身没有任何问题。但是，聪明的你可能意识到：函数中定义了一个大型的数组，会不会是它造成的？ 实际确实是这样，有...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"为什么局部大数组容易导致栈溢出\\",\\"image\\":[\\"\\"],\\"dateModified\\":null,\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://lishutong1024.cn/tech/rtos100/g7ysdksn/"}],["meta",{"property":"og:site_name","content":"李述铜的嵌入式课堂"}],["meta",{"property":"og:title","content":"为什么局部大数组容易导致栈溢出"}],["meta",{"property":"og:description","content":"刚刚帮一位学习RTOS课程的同学调试他的工程时，发现他的程序运行一段时间后就死机了，但是复位后又能正常跑，但是过一会儿又死。 通过加入测试代码并反复测试分析，最终发现问题出现在了一个大数组上。简单来说，他写了这样一段代码： 就语法而言，这段代码本身没有任何问题。但是，聪明的你可能意识到：函数中定义了一个大型的数组，会不会是它造成的？ 实际确实是这样，有..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}]]},"readingTime":{"minutes":6.29,"words":1886},"git":{},"autoDesc":true,"filePathRelative":"notes/tech/rtos100/task/q29.md","headers":[],"bulletin":true}');export{A as comp,u as data};
